import{_ as t,o as e,c as o,aj as r}from"./chunks/framework.Cn87zHeG.js";const q=JSON.parse('{"title":"H1 调试工具常见问题","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/factory-test.md","filePath":"faq/factory-test.md"}'),n={name:"faq/factory-test.md"};function s(d,a,h,i,l,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="出厂与跑机测试" tabindex="-1">H1 调试工具常见问题 <a class="header-anchor" href="#出厂与跑机测试" aria-label="Permalink to &quot;H1 调试工具常见问题 {#出厂与跑机测试}&quot;">​</a></h1><p>H1 调试工具用于建图、定位、导航、执行器检查和系统诊断，需固件 <strong>不低于 1.0.026.260525</strong>。首次使用请先阅读 <a href="./../getting-started/debug-tool.html">H1 调试工具使用说明</a>。</p><h2 id="q20" tabindex="-1">Q20. H1 调试工具怎么访问？ <a class="header-anchor" href="#q20" aria-label="Permalink to &quot;Q20. H1 调试工具怎么访问？ {#q20}&quot;">​</a></h2><p>与网络配置工具接入方式相同，但使用 <strong>8090 端口</strong>，无需登录。网线直连地址为 <code>http://10.42.0.2:8090</code>，机器人热点地址为 <code>http://192.168.60.1:8090</code>；同一局域网内使用 <code>http://&lt;机器人IP&gt;:8090</code>。</p><p><span id="wired-direct"></span><span id="wired-ubuntu"></span><span id="wired-windows"></span></p><p>如果已能打开 8080 端口的网络配置工具，无需重复设置电脑 IP。Ubuntu / Windows 有线设置和接入步骤见<a href="./../getting-started/debug-tool.html#connect">连接 H1 调试工具</a>。</p><h2 id="q21" tabindex="-1">Q21. 页面顶部的彩色状态标记是什么意思？ <a class="header-anchor" href="#q21" aria-label="Permalink to &quot;Q21. 页面顶部的彩色状态标记是什么意思？ {#q21}&quot;">​</a></h2><p><strong>绿 = 当前正常，黄 = 消息更新超时，红 = 指令响应超时，灰 = 尚未收发</strong>。灰色可能是尚未收到消息，也可能是发布接口还未发送，本身不代表故障。应结合接口方向及异常详情排查，再进行依赖该接口的操作。见<a href="./../getting-started/debug-tool.html#status">查看状态</a>。</p><h2 id="q22" tabindex="-1">Q22. 建图期间为什么不能做其他测试？ <a class="header-anchor" href="#q22" aria-label="Permalink to &quot;Q22. 建图期间为什么不能做其他测试？ {#q22}&quot;">​</a></h2><p>建图期间，定位和导航会被锁定。需要先完成建图，再进行后续操作。建图起点、遥控扫描和保存地图的步骤见<a href="./../getting-started/debug-tool.html#mapping">建图</a>。</p><h2 id="q23" tabindex="-1">Q23. 怎么判断定位成功？ <a class="header-anchor" href="#q23" aria-label="Permalink to &quot;Q23. 怎么判断定位成功？ {#q23}&quot;">​</a></h2><p>需先建好地图，定位状态显示 <code>locating_success</code> 才表示定位成功，可以继续导航。定位的准备条件和操作见<a href="./../getting-started/debug-tool.html#localization">定位</a>。</p><h2 id="q24" tabindex="-1">Q24. 导航目标有哪些设置方式？ <a class="header-anchor" href="#q24" aria-label="Permalink to &quot;Q24. 导航目标有哪些设置方式？ {#q24}&quot;">​</a></h2><p>可使用 <strong>P1–P4 预设点</strong>，也可填写 <code>x / y / yaw</code> 自定义位姿，其中 <code>yaw</code> 使用弧度。灰色预设点表示尚未录入。具体操作见<a href="./../getting-started/debug-tool.html#navigation">导航</a>。</p><h2 id="q25" tabindex="-1">Q25. 预设点如何保存，重启后要检查什么？ <a class="header-anchor" href="#q25" aria-label="Permalink to &quot;Q25. 预设点如何保存，重启后要检查什么？ {#q25}&quot;">​</a></h2><p><strong>重启或更换地图、场景后，先核对点位坐标，再下发导航</strong>。点位缺失或与当前场景不匹配时，应重新录入。录入前需确认定位状态为 <code>locating_success</code>；录入方法见<a href="./../getting-started/debug-tool.html#waypoints">记录预设点</a>。</p><h2 id="q26" tabindex="-1">Q26. 怎么中止正在进行的导航？ <a class="header-anchor" href="#q26" aria-label="Permalink to &quot;Q26. 怎么中止正在进行的导航？ {#q26}&quot;">​</a></h2><p>使用导航页的 <strong>取消当前任务</strong>，并确认任务状态和机器人实际运动已停止。按钮位置和操作见<a href="./../getting-started/debug-tool.html#cancel-navigation">取消导航</a>。</p><h2 id="q29" tabindex="-1">Q29. 出现问题时，应该给技术支持哪些信息？ <a class="header-anchor" href="#q29" aria-label="Permalink to &quot;Q29. 出现问题时，应该给技术支持哪些信息？ {#q29}&quot;">​</a></h2><p>提供问题现象、发生时间、复现步骤，以及「系统诊断 → 接口健康」中的 <strong>诊断信息</strong>。其中包含话题状态、所属组、更新时间和异常详情，便于定位问题。复制方法见<a href="./../getting-started/debug-tool.html#diagnostics">系统诊断</a>。</p><h2 id="q30" tabindex="-1">Q30. 摄像头没有画面或帧率偏低，一定是故障吗？ <a class="header-anchor" href="#q30" aria-label="Permalink to &quot;Q30. 摄像头没有画面或帧率偏低，一定是故障吗？ {#q30}&quot;">​</a></h2><p>不一定。画面数量和类型取决于设备配置，未安装的选配相机（如头部 D435）无图不代表故障。预览会占用带宽和处理资源，显示帧率也受相机与网络影响，关闭预览后会释放订阅。</p><p>查看方法见<a href="./../getting-started/debug-tool.html#cameras">摄像头预览</a>；相机话题和 QoS 见<a href="./../hardware/sensors.html">传感器</a>。</p><h2 id="q31" tabindex="-1">Q31. 机器人日志在哪里下载？ <a class="header-anchor" href="#q31" aria-label="Permalink to &quot;Q31. 机器人日志在哪里下载？ {#q31}&quot;">​</a></h2><p>在「系统诊断 → 接口健康」中使用 <strong>打包下载日志</strong>，下载 ZIP 日志包。日志量较大时打包需要更长时间，请根据页面进度和提示判断状态。具体操作见<a href="./../getting-started/debug-tool.html#logs">下载日志</a>。</p><h2 id="q32" tabindex="-1">Q32. 录制 ROS Bag 有哪些限制？ <a class="header-anchor" href="#q32" aria-label="Permalink to &quot;Q32. 录制 ROS Bag 有哪些限制？ {#q32}&quot;">​</a></h2><p>同一时刻只允许一个录制任务；开始手动录制前须关闭自动录制。<strong>手动录制时，磁盘剩余低于 2 GiB 会自动停止</strong>，且不能开始新的手动录制。自动录制采用分段回收，仅在排查需要时开启。相机、点云等话题数据量较大，应按分析需要选择。停止后需等待写入完成，不要断电；下载并确认数据可用后，及时清理机器人上的录制文件，避免磁盘写满。</p><p>录制、下载和清理方法见<a href="./../getting-started/debug-tool.html#rosbag">ROS Bag 录制</a>。</p><h2 id="q33" tabindex="-1">Q33. 升降与头部可以查看和控制哪些功能？ <a class="header-anchor" href="#q33" aria-label="Permalink to &quot;Q33. 升降与头部可以查看和控制哪些功能？ {#q33}&quot;">​</a></h2><p>「硬件测试 → 执行器」页可查看升降与头部的 <strong>6 路限位状态</strong>、头部堵转及升降报警，并支持校准与手动微调。限位状态绿表示未触发，黄表示已触发；报警时应先停止操作、排除机械卡阻，再处理对应报警。</p><p>该页会直接驱动升降与头部执行器，操作前确认周围无人、上方及头部运动范围无遮挡。具体操作见<a href="./../getting-started/debug-tool.html#actuators">升降与头部控制</a>。</p>',31)])])}const p=t(n,[["render",s]]);export{q as __pageData,p as default};
